{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원 점용허가 후 실제 사용 면적이 허가 면적보다 작은 경우, 허가기간이 남아 있을 때 낸 점용료를 일부 돌려받을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제19조제2항에 따르면, 이미 납부된 사용료·점용료는 사용수익허가 또는 점용허가 기간 내에 환불할 수 있는 사유가 있으면 그 전부 또는 일부를 환불할 수 있습니다. 같은 항 제2호는 실제의 공원점용 면적이 점용허가 면적보다 과소하거나 요금산정의 착오 등 환불이 불가피하다고 인정되는 경우를 환불 사유로 정하고 있습니다. 따라서 실제 사용 면적이 허가 면적보다 작게 확인된 경우는 이 환불 사유에 해당할 수 있으며, 허가기간이 남아 있더라도 환불이 불가피하다고 인정되면 낸 점용료의 전부 또는 일부를 돌려받을 수 있습니다.",
          "b_ids": "도시공원:제19조제2항, 도시공원:제19조제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
